# -*- coding: utf-8 -*-
# 批注数据：src/utils/sessionStorage.ts（5105 行，会话转录 JSONL 的读写层）
# slug = src_utils_sessionStorage_ts
ANNOTATIONS = [
    (95, 'after', r'''文件级：整个会话持久化的唯一入口——把内存里的 Message 追加进 JSONL、把 JSONL 读回成会话链、维护 /resume 列表所需的元数据。所有路径都落在 `~/.claude/projects/<清洗后的工程路径>/<sessionId>.jsonl`。'''),
    (106, 'after', r'''Transcript 类型：能进转录的四种消息（user/assistant/attachment/system）。progress 故意不在其中——它是纯 UI 状态，写进链会造出分叉，把真实消息挤成孤儿。'''),
    (146, 'after', r'''isTranscriptMessage：判定某条目是否属于转录——单一事实来源，加载时靠它决定哪些进消息表。progress 明确排除（历史上写进去过，导致 #14373/#23537 的链分叉）。'''),
    (156, 'after', r'''isChainParticipant：判断某消息是否参与 parentUuid 链。progress 不参与——它会被写进文件，但没有任何消息挂在它下面。'''),
    (178, 'after', r'''isLegacyProgressEntry：兼容老转录里残留的 progress 条目（新版 Entry 联合类型里已经没有它，但磁盘上还有）。加载时用它做桥接，避免老会话在链上断掉。'''),
    (196, 'after', r'''isEphemeralToolProgress：高频的纯 UI 进度类型（bash/powershell/mcp，及实验开关下的 sleep）——每秒一条，不进 API、工具结束后也不渲染。'''),
    (205, 'after', r'''getTranscriptPath：当前会话的 JSONL 路径。优先用 sessionProjectDir（resume/分支时被切过），回落才用 originalCwd 推导——两者不一致会导致「保存到一个目录、却从另一个目录找」的分裂脑。'''),
    (225, 'after', r'''getTranscriptPathForSession：按 sessionId 求路径。当前会话要走同样的 sessionProjectDir 逻辑（否则 hook 拿到的 transcript_path 会指向另一个目录，见 gh-30217）；其他会话只能靠 originalCwd 猜。'''),
    (229, 'after', r'''MAX_TRANSCRIPT_READ_BYTES：50MB 上限。会话文件能涨到几个 GB（inc-3930），读原始转录的调用方超过这个阈值必须放弃，否则直接 OOM。'''),
    (258, 'after', r'''getAgentTranscriptPath：子代理转录路径 = 项目目录/会话ID/subagents[/子目录]/agent-<id>.jsonl。子目录映射用来给工作流类的多个子代理分组。'''),
    (262, 'after', r'''getAgentMetadataPath：把 `.jsonl` 换成 `.meta.json`——用旁挂文件存 agentType 等信息，避免改 JSONL 的 schema。'''),
    (272, 'after', r'''AgentMetadata 类型：agentType 必填；worktreePath 记录隔离的执行目录（resume 时能恢复正确 cwd）；description 存原始任务描述（老文件可能没有）。'''),
    (290, 'after', r'''writeAgentMetadata：写旁挂元数据。不写的话，省略 subagent_type 去 resume 会静默降级成 general-purpose——系统提示从 4KB 变成通用版，且不继承历史。'''),
    (303, 'after', r'''readAgentMetadata：文件不可访问（不存在/无权限）返回 null，其余错误照抛——把「没有」与「读坏了」分开，避免掩盖真实故障。'''),
    (318, 'after', r'''RemoteAgentMetadata 类型：远端任务的身份信息（taskId、CCR sessionId、标题、命令、启动时间）。状态永远从 CCR 实时拉，本地只存身份。'''),
    (344, 'after', r'''writeRemoteAgentMetadata：按任务写一个旁挂文件。它在 subagents 的同级目录，因此不会被 hydrateSessionFromRemote 的 JSONL 覆盖动作清掉。'''),
    (357, 'after', r'''readRemoteAgentMetadata：读远端任务元数据，不可访问时返回 null。'''),
    (367, 'after', r'''deleteRemoteAgentMetadata：删除旁挂文件，同样把「不存在」当成功处理。'''),
    (399, 'after', r'''listRemoteAgentMetadata：扫目录收集所有 `*.meta.json`。单个文件读坏只跳过并记日志——半截写入不该让整次恢复失败。'''),
    (411, 'after', r'''sessionIdExists：只 stat 一下会话文件是否存在，用于校验用户输入的 sessionId。'''),
    (421, 'after', r'''getUserType：读环境变量 USER_TYPE，默认 external。后面多处用它区分内部（ant）与外部用户的行为差异。'''),
    (438, 'after', r'''getProjectDir：工程路径 → 项目目录名，用 memoize 缓存。每轮会被调用十几次（经 hooks 的 createBaseHookInput），而 homedir/env/正则都是会话内不变的，所以缓存安全。'''),
    (467, 'after', r'''getProject：Project 单例的懒初始化，并注册一次清理钩子——退出时先 flush 队列，再把会话元数据重新追加到文件尾（否则 /rename 的标题会被后续消息挤出 64KB 尾部窗口）。'''),
    (503, 'after', r'''setInternalEventWriter：注册 CCR v2 的内部事件写入器。注册后转录走 worker 内部事件，不再走 v1 的 Session Ingress。'''),
    (520, 'after', r'''setInternalEventReader：注册 CCR v2 的读取器（主线程 + 子代理各一个），供重连时回灌会话状态。'''),
    (528, 'after', r'''setRemoteIngressUrlForTesting：测试用，模拟 hydrateRemoteSession 设好远端地址后的状态。'''),
    (570, 'after', r'''Project 类：单例持有当前会话的路径缓存、待写队列、远端写入器与各类会话元数据缓存。所有写盘都经它的队列串行化，避免并发追加互相截断。'''),
    (604, 'after', r'''trackWrite：包一层待写计数——flush() 靠它等待「不在队列里」的写（如 removeMessageByUuid）也完成。'''),
    (616, 'after', r'''enqueueWrite：把条目塞进按文件分的写队列，并调度一次 drain。返回的 Promise 在该条目真正落盘时 resolve，调用方可选择等或不等。'''),
    (632, 'after', r'''scheduleDrain：100ms 定时器合并写（远端模式降到 10ms）。drain 期间新到的条目会让它再调度一轮，保证不丢。'''),
    (643, 'after', r'''appendToFile：追加写，权限 0600。首次失败不区分错误码，直接补建目录后重试——NFS 类文件系统返回的错误码不可靠，没法按码判断。'''),
    (686, 'after', r'''drainWriteQueue：一次把每个文件的队列取空，拼成字符串批量追加；单块超过 100MB 就先落盘再续，避免一次分配过大。落完 resolve 对应条目并清掉空队列。'''),
    (691, 'after', r'''resetSessionFile：清空当前会话文件指针与待写缓冲（切会话/重新生成 ID 时用），新文件延后到第一条 user/assistant 消息才真正创建。'''),
    (839, 'after', r'''reAppendSessionMetadata：把会话级元数据重新追加到文件尾。三个要点：① 先同步读尾部，吸收外部（SDK）刚写入的更新的标题/标签，防止用陈旧缓存覆盖；② 写入顺序让 customTitle/tag 更靠近 EOF——尾部读取只扫最后 64KB；③ 无条件重写，因为压缩后标题会被推出窗口。'''),
    (861, 'after', r'''flush：取消定时器、等在途 drain、再排空队列，最后等非队列写完成。退出与测试都靠它保证「已经写下去了」。'''),
    (951, 'after', r'''removeMessageByUuid：墓碑式删除。快路径只读尾部 64KB、按 `uuid` 键整段匹配（避免命中子条目里的 parentUuid）、定位行边界后用 truncate + 回写尾部；目标不在窗口内才走整文件重写，且超过 50MB 直接放弃。'''),
    (970, 'after', r'''shouldSkipPersistence：统一的写盘闸门——测试环境（除非显式开启）、cleanupPeriodDays=0、--no-session-persistence、SKIP_PROMPT_HISTORY 任一成立就不写。'''),
    (991, 'after', r'''materializeSessionFile：第一条 user/assistant 消息到来时才创建会话文件并写入启动期缓存的元数据，然后冲刷缓冲条目——避免产生「只有元数据、没有对话」的空会话文件。'''),
    (1083, 'after', r'''insertMessageChain：写入一条消息链并维护 parentUuid 游标。工具结果消息会用 sourceToolAssistantUUID 覆盖父节点（保证结果挂在发起调用的那条 assistant 下）；会话戳字段必须放在展开之后，否则 fork/resume 会带着源会话的 sessionId 落盘。'''),
    (1099, 'after', r'''insertFileHistorySnapshot：写文件历史快照条目（供 rewind 恢复文件状态）。'''),
    (1126, 'after', r'''insertContentReplacement：写内容替换记录（工具结果被预算裁剪时的映射），子代理按 agentId 落 sidechain 文件、主线程按 sessionId 落会话文件。'''),
    (1265, 'after', r'''appendEntry：真正的分流入口。元数据类条目一律直接入队；消息类条目要先查 UUID 是否已存在——但子代理 sidechain 的本地写入跳过去重，因为它写到另一个文件，fork 继承来的消息 UUID 与主会话重复（去重会让 sidechain 只剩 10KB 而不是完整 85KB）。'''),
    (1277, 'after', r'''ensureCurrentSessionFile：懒设当前会话文件路径，不主动创建文件——没内容就不该有文件。'''),
    (1300, 'after', r'''getExistingSessionFile：查另一个会话的文件是否存在，命中结果缓存，避免重复 stat。'''),
    (1343, 'after', r'''persistToRemote：远端持久化。优先走 CCR v2 内部事件（带 isCompaction / agentId 标记）；否则走 v1 Session Ingress，失败就记事件并优雅退出——远端写失败意味着会话无法恢复，硬撑没有意义。'''),
    (1352, 'after', r'''setRemoteIngressUrl：开启远端持久化，并把合并窗口从 100ms 压到 10ms——远端模式下消息延迟要尽量小。'''),
    (1384, 'after', r'''Project 类到此结束。往下是本模块对外的函数式 API：record* 负责写、load*/get* 负责读、save* 负责元数据。'''),
    (1389, 'after', r'''TeamInfo 类型：团队名 + 代理名，随消息一起落盘，用于 /resume 里区分不同代理的会话。'''),
    (1449, 'after', r'''recordTranscript：写转录的主入口。先过滤掉已记录的 UUID 再交给 insertMessageChain——否则压缩后的 messagesToKeep 会推进父游标，让新消息挂到压缩前的 UUID 上，把压缩边界变成孤儿。已记录消息只在「构成前缀」时才当父节点（压缩场景下它们排在新边界之后，不能当父）。'''),
    (1462, 'after', r'''recordSidechainTranscript：写子代理的旁链转录（isSidechain=true，带 agentId）。'''),
    (1474, 'after', r'''removeTranscriptMessage：对外暴露的墓碑删除，用于收到孤儿消息的 tombstone 时清理。'''),
    (1499, 'after', r'''recordContentReplacement：对外暴露的内容替换记录写入。'''),
    (1507, 'after', r'''resetSessionFilePointer：切会话/重新生成 ID 后重置文件指针，新文件延后创建。'''),
    (1534, 'after', r'''adoptResumedSessionFile：--continue/--resume（非 fork）时直接接管已存在的文件。必须在这里设好指针，否则「-c 后立刻退出」的场景里内存缓存是对的、却永远写不下去（清理钩子在指针为 null 时直接返回）。'''),
    (1556, 'after', r'''recordContextCollapseCommit：写上下文折叠的提交条目。一条提交一行，顺序即提交顺序——恢复时要靠顺序重建折叠日志。'''),
    (1581, 'after', r'''recordContextCollapseSnapshot：写折叠暂存队列的快照（每次 spawn 解析后写一次），恢复时后写的覆盖先写的。'''),
    (1585, 'after', r'''flushSessionStorage：对外暴露的 flush，退出前调用确保全部落盘。'''),
    (1622, 'after', r'''hydrateRemoteSession：把远端会话日志拉到本地并整体覆盖本地文件（writeFile 自带截断）。远端地址在 finally 里才设置——必须先同步完再开持久化，否则新写入会和回灌内容打架。'''),
    (1723, 'after', r'''hydrateFromCCRv2InternalEvents：从 CCR v2 内部事件回灌。前台事件写主转录，子代理事件按 agent_id 分组各写各的文件；epoch 不匹配（409）要原样抛出，让 worker 停止而不是和优雅退出抢时序。'''),
    (1740, 'after', r'''extractFirstPrompt：把第一条有意义的用户消息压成单行、截到 200 字，作为 /resume 列表里的标题；找不到就用「No prompt」兜底。'''),
    (1812, 'after', r'''getFirstMeaningfulUserMessageTextContent：跳过 meta 消息与压缩摘要；数组内容要遍历所有文本块（VS Code 的 IDE 标签在前，真实提问藏在后面）。斜杠命令只在自定义命令带参数时才算有意义，bash 输入统一加 ! 前缀。'''),
    (1821, 'after', r'''removeExtraFields：序列化前剥掉 isSidechain / parentUuid 两个字段——它们是链的内部结构，不该出现在对外导出的消息里。'''),
    (1956, 'after', r'''applyPreservedSegmentRelinks：压缩后把「保留段」接回链上。保留段的消息在磁盘上还带着压缩前的 parentUuid（去重跳过写入，改不了），所以只能就地打补丁：head 指向 anchor，anchor 的其他孩子改指 tail，再把保留段 assistant 消息的 usage 清零——否则 resume 后立刻触发自动压缩。最后删掉最后一个边界之前的全部非保留消息。'''),
    (2039, 'after', r'''applySnipRemovals：重放 snip 的删除。snip 删的是中间区间，JSONL 又是追加式，幸存消息的 parentUuid 会指向已删区间——所以删完必须重新连边（沿被删条目的父链回溯到第一个幸存的祖先），并做路径压缩避免重复回溯。'''),
    (2061, 'after', r'''findLatestMessage：O(n) 单遍找时间戳最新的匹配项，替掉「filter + sort + [0]」那种 O(n log n) 且大量分配 Date 的写法。'''),
    (2094, 'after', r'''buildConversationChain：从叶子沿 parentUuid 一路走到根，遇环就记日志并返回部分链，最后反转成根→叶顺序，再补一轮「被单父遍历漏掉的兄弟块」恢复。'''),
    (2206, 'after', r'''recoverOrphanedParallelToolResults：修复流式产物的星形拓扑。并发工具调用会产生多条同 message.id 的 assistant（各自一个块），单父遍历只能走通一条分支——这里按 message.id 分组，把链外的兄弟与它们的 tool_result 按时间戳补到最后一个链上成员之后，保证每段工具结果都紧跟自己的调用。'''),
    (2243, 'after', r'''checkResumeConsistency：拿最后一个 turn_duration 检查点里记录的 messageCount 与它在重建链里的实际位置比较，上报 delta。正数=恢复出的消息比会话内多（常见故障），负数=链被截断。'''),
    (2272, 'after', r'''buildFileHistorySnapshotChain：按会话顺序收集文件快照；isSnapshotUpdate 的条目替换同 messageId 的旧快照，其余追加。'''),
    (2286, 'after', r'''buildAttributionSnapshotChain：归因快照用生成的 UUID、表示累积状态，所以整份返回（不像文件快照要按消息顺序挑）。'''),
    (2392, 'after', r'''loadTranscriptFromFile：读单个转录文件成 LogOption。JSONL 走完整加载（找最新叶子→建链→附摘要与元数据）；老式 JSON 兼容「裸数组」与「带 messages 字段的对象」两种形状。'''),
    (2424, 'after', r'''hasVisibleUserContent：判断用户消息在 UI 里是否可见——meta 不可见，纯 tool_result 不可见，只有文本/图片/文档块才算。'''),
    (2443, 'after', r'''hasVisibleAssistantContent：assistant 只有含非空白文本块才算可见（纯 tool_use 会被折叠成工具组，不单独占一条对话）。'''),
    (2477, 'after', r'''countVisibleMessages：统计真正会显示成对话轮次的消息数——/resume 里的消息条数就是这个口径，不是文件行数。'''),
    (2524, 'after', r'''convertToLogOption：把消息链打包成列表项：时间取首末消息的时间戳、标题取第一条有效提问、条数取可见消息数，并带上分支/团队/PR/快照等附属信息。'''),
    (2557, 'after', r'''trackSessionBranchingAnalytics：统计同一 sessionId 出现多份转录的分支情况（rewind 会造分支），只有真存在分支时才上报。'''),
    (2566, 'after', r'''fetchLogs：取当前工程目录下的会话列表（stat-only 的 lite 版），顺带上报分支统计。'''),
    (2584, 'after', r'''appendEntryToFile：同步追加一行 JSON，失败就补建目录再试。同步是因为调用方本身是同步的（退出清理、materialize）。'''),
    (2614, 'after', r'''readFileTailSync：同步读文件尾部一个缓冲区大小，用 fstat 拿大小避免额外路径查找；任何错误都返回空串，让调用方回落到「缓存即真值」的行为。'''),
    (2638, 'after', r'''saveCustomTitle：写用户标题条目并更新当前会话缓存，同时上报重命名事件（区分用户改名与自动命名）。'''),
    (2673, 'after', r'''saveAiGeneratedTitle：AI 标题单独用 ai-title 条目而不复用 custom-title——读取时 customTitle 优先，所以用户改名永远盖过 AI；恢复时也只会回填用户标题，避免陈旧 AI 标题覆盖会话中的手动改名。'''),
    (2688, 'after', r'''saveTaskSummary：给 `claude ps` 用的滚动任务摘要。故意不被 reAppendSessionMetadata 重写——它只表示「此刻在做什么」，过期没关系。'''),
    (2699, 'after', r'''saveTag：写标签条目并更新缓存，用于给会话分类。'''),
    (2729, 'after', r'''linkSessionToPR：把会话与 GitHub PR 关联（编号/URL/仓库），并写进缓存，压缩后能被重新追加回去。'''),
    (2737, 'after', r'''getCurrentSessionTag：只对当前会话返回标签——缓存里只有当前会话的元数据。'''),
    (2747, 'after', r'''getCurrentSessionTitle：同上，只返回当前会话标题。'''),
    (2751, 'after', r'''getCurrentSessionAgentColor：代理配色，当前会话唯一持有。'''),
    (2785, 'after', r'''restoreSessionMetadata：resume 时把磁盘元数据灌回缓存。标题用 ??= 赋值，让 --name 传入的标题优先于被恢复会话的原标题（REPL 在 /resume 前会先清缓存，所以不影响正常恢复）。'''),
    (2805, 'after', r'''clearSessionMetadata：/clear 新建会话时清空全部缓存字段，避免上个会话的标题/标签/代理色泄漏到新会话。'''),
    (2817, 'after', r'''reAppendSessionMetadata 的对外包装：压缩后调用，把元数据重新写回文件尾，保证尾部窗口读得到标题。'''),
    (2836, 'after', r'''saveAgentName：写代理名条目、更新缓存，并同步刷新并发会话列表里的名字。'''),
    (2854, 'after', r'''saveAgentColor：写代理配色条目并更新缓存。'''),
    (2863, 'after', r'''saveAgentSetting：只写缓存，落盘交给第一条消息时的 materializeSessionFile——启动期就写盘会造出只有元数据的空会话文件。'''),
    (2872, 'after', r'''cacheSessionTitle：--name 传入的标题也只进缓存，同样避免过早建文件。'''),
    (2881, 'after', r'''saveMode：缓存 coordinator/normal 模式，落盘时机同上。'''),
    (2920, 'after', r'''saveWorktreeState：记录 worktree 状态供 --resume 用。先剥掉 creationDurationMs / usedSparsePaths 等临时字段（结构化类型允许传完整对象，但不该序列化进去）；文件已存在时立刻写，否则等第一条消息。'''),
    (2934, 'after', r'''getSessionIdFromLog：lite 日志直接读 sessionId 字段；完整日志从第一条消息里取。'''),
    (2942, 'after', r'''isLiteLog：messages 为空且有 sessionId——说明只是 stat 出来的壳，要读文件才能补全。'''),
    (3056, 'after', r'''loadFullLog：把 lite 日志补成完整日志。找最新叶子（限 user/assistant）→ 建链 → 用加载出的元数据覆盖壳里的空字段；任何异常都原样返回入参，让列表至少能显示。'''),
    (3106, 'after', r'''searchSessionsByCustomTitle：按标题搜会话。默认跨同一仓库的 worktree 搜；同一 sessionId 的多个分支只留最新的那份；最后按修改时间倒序。'''),
    (3126, 'after', r'''METADATA_PREFIX_BOUND：元数据标记的最长前缀长度（22 字节标记 + 前导花括号）。用它判断跨块的残留行是否「值得拼起来再看」。'''),
    (3147, 'after', r'''resolveMetadataBuf：处理跨块的行。残留够长且以 `{` 开头时，逐个比对标记前缀决定要不要拼接；否则直接跳过整块，保证常见情况（无元数据）不做字符串拼接。'''),
    (3224, 'after', r'''scanPreBoundaryMetadata：在压缩边界之前做一次只抓元数据行的正向扫描。用原始 Buffer + 字节级标记匹配，避免对 99% 的消息行做逐行字符串转换；某块没有任何标记就整块跳过。'''),
    (3304, 'after', r'''pickDepthOneUuidCandidate：一行里出现多个 `uuid`+`timestamp` 候选时，用一个字符串感知的花括号计数器找出嵌套深度为 1 的那个——嵌套消息（agent_progress）与服务器可控对象都可能伪造出同样的字节序列。'''),
    (3466, 'after', r'''walkChainBeforeParse：解析之前先按字节砍掉死分支。扫一遍建立行索引与 uuid→槽位映射，从最后一个非 sidechain 条目沿父链回溯，只保留链上条目与全部元数据行；且只在「能砍掉至少一半字节」时才真的拼接，否则索引开销大于解析收益。'''),
    (3813, 'after', r'''loadTranscriptFile：加载器核心。① 大文件先做边界截断与预扫描，② 可选地砍死分支，③ 先处理边界前的元数据行，④ 用 progress 桥接表修复老转录的链，⑤ 逐条分流进消息表与各类元数据表，⑥ 应用压缩保留段重连与 snip 重放，⑦ 算出所有叶子 UUID。'''),
    (3836, 'after', r'''loadSessionFile：按 sessionId 拼出路径后复用 loadTranscriptFile。'''),
    (3848, 'after', r'''getSessionMessages：memoize 的「会话已有 UUID 集合」。写入路径每条消息都要查重，重复读同一个文件会很贵。'''),
    (3856, 'after', r'''clearSessionMessagesCache：压缩后旧 UUID 失效，必须清缓存，否则新消息会被误判为「已存在」而跳过写入。'''),
    (3867, 'after', r'''doesMessageExistInSession：查某个 UUID 是否已在会话里（对外的小工具）。'''),
    (3932, 'after', r'''getLastSessionLog：一次读盘拿到全部数据，取最后一条非 sidechain 消息建链并组装 LogOption。顺带「预热」UUID 缓存——但只在缓存为空时填，否则会把未落盘的 UUID 覆盖掉，破坏去重。'''),
    (3956, 'after', r'''loadMessageLogs：当前工程的会话列表（补全元数据后按时间排序、重编索引）。'''),
    (3976, 'after', r'''loadAllProjectsMessageLogs：跨全部工程的会话列表。skipIndex 时走「全量加载」（/insights 要全部分支），否则走渐进式（先补 50 条，其余按需）。'''),
    (4016, 'after', r'''loadAllProjectsMessageLogsFull：逐工程全量加载并按 sessionId+leafUuid 去重（同一会话可能出现在多个工程目录），保留修改时间最新的一份。'''),
    (4049, 'after', r'''loadAllProjectsMessageLogsProgressive：先 stat 出全部会话、按 sessionId 去重排序，再只补前 initialEnrichCount 条，其余留给后续滚动加载——首屏快，且能继续。'''),
    (4071, 'after', r'''SessionLogResult 类型：渐进加载的三件套——已补全的日志、完整 stat 列表、下次继续的位置。'''),
    (4084, 'after', r'''loadSameRepoMessageLogs：同仓库多 worktree 的会话列表（渐进版的薄包装）。'''),
    (4108, 'after', r'''loadSameRepoMessageLogsProgressive：按 worktree 路径集合收集会话并补全首批元数据，日志里打印实际扫到的文件数，便于排查「worktree 会话看不见」。'''),
    (4181, 'after', r'''getStatOnlyLogsForWorktrees：纯 stat 收集，不读文件内容。worktree 路径按清洗后前缀长度降序匹配，避免短前缀（如 -code-repo）先把长前缀（-code-repo-worktree1）的目录抢走；Windows 下盘符大小写不敏感。最后按 sessionId 去重。'''),
    (4236, 'after', r'''getAgentTranscript：读子代理转录。按 agentId 过滤出 sidechain 消息，找最新叶子建链，再过滤一次（链上可能混入主线程消息），最后剥掉内部字段返回。'''),
    (4263, 'after', r'''extractAgentIdsFromMessages：从 progress 消息里提取 agentId（agent_progress / skill_progress），用于找回同步执行过的子代理。'''),
    (4292, 'after', r'''extractTeammateTranscriptsFromTasks：直接从 AppState 的 in_process_teammate 任务里取消息——每个队友回合用随机 agentId 存盘，磁盘路径不可靠，内存里的反而准。'''),
    (4322, 'after', r'''loadSubagentTranscripts：并发加载多个子代理转录，单个失败就跳过（不拖累其他）。'''),
    (4347, 'after', r'''loadAllSubagentTranscriptsFromDisk：直接扫会话目录下的 subagents/ 找 `agent-*.jsonl`——不依赖 AppState，任务被驱逐后仍能找回。文件名格式是 getAgentTranscriptPath 的逆运算，改一处要同步改另一处。'''),
    (4367, 'after', r'''isLoggableMessage：能否落盘。progress 一律不写；非内部用户默认丢弃附件（含训练敏感信息），只有显式开启时才放行 hook_additional_context。'''),
    (4381, 'after', r'''collectReplIds：收集 REPL 工具的 tool_use id，供下一步把 REPL 包装从转录里抹掉。id 必须从「完整消息数组」收集——增量切片会把调用与结果拆到两次写入里，各收一次就会漏。'''),
    (4448, 'after', r'''transformMessagesForExternalTranscript：外部用户的转录里隐藏 REPL 层——剥掉 REPL 的 tool_use 与对应 tool_result，并把 isVirtual 消息提升为真实消息。模型 resume 后看到的是「直接调 Bash/Read」的干净历史。'''),
    (4461, 'after', r'''cleanMessagesForLogging：写盘前的统一清洗：先按 isLoggableMessage 过滤，非内部用户再做 REPL 剥离。'''),
    (4471, 'after', r'''getLogByIndex：按序号取一条完整日志（内部会全量加载列表，慎在热路径调用）。'''),
    (4519, 'after', r'''findUnresolvedToolUse：按 tool_use_id 找还没配对的调用。扫到对应 tool_result 就直接返回 null——「已有结果」也算不需要恢复。'''),
    (4569, 'after', r'''getSessionFilesWithMtime：扫工程目录下所有 `*.jsonl`，用 validateUuid 过滤文件名（防止非法名混入），并发 stat 批量取 mtime/ctime/size。'''),
    (4577, 'after', r'''INITIAL_ENRICH_COUNT：首屏补全 50 条。每条最多读 128KB（头+尾），50 条约 6.4MB I/O——比原来只补 10 条的首屏体验好得多。'''),
    (4592, 'after', r'''LiteMetadata 类型：头尾扫描能拿到的轻量元数据（首条提问、分支、标题、标签、PR 等），不含任何消息内容。'''),
    (4694, 'after', r'''loadAllLogsFromSessionFile：为一个文件里的每个叶子各造一条日志（/insights 要按分支看）。先建 parentUuid→children 索引，把叶子的尾随子消息按时间戳补到链尾。'''),
    (4729, 'after', r'''getLogsWithoutIndex：绕开会话索引，按 mtime 取最近 N 个文件全量加载；单文件失败只记日志继续。'''),
    (4813, 'after', r'''readLiteMetadata：只读头尾各 64KB 提取元数据。标题优先级：尾部的 lastPrompt → 头部扫出的首条提问 → 内容前缀兜底；标题字段优先 customTitle 再 aiTitle（用户命名永远赢）；PR 编号是数字，字符串提取失败时再按 `prNumber` 手扫一次。'''),
    (4914, 'after', r'''extractFirstPromptFromChunk：逐行找第一条有意义的 user 消息。跳过 tool_result、meta 与 XML 类通知；内置斜杠命令只作兜底标题，带参数的自定义命令原样显示；bash 输入加 ! 前缀；全是 tick 的主动会话给一个合成标题，免得被过滤掉。'''),
    (4949, 'after', r'''extractJsonStringFieldPrefix：截断缓冲区专用——引号没闭合时也能取出前 maxLen 个字符，转义序列换成空格，用来兜底超大首条消息的标题。'''),
    (4968, 'after', r'''deduplicateLogsBySessionId：按 sessionId 去重保留最新，排序后重编索引。'''),
    (5016, 'after', r'''getSessionFilesLite：纯 stat 的会话列表——不读任何文件内容，瞬间返回；标题/分支等信息由 enrichLogs 后续补。'''),
    (5070, 'after', r'''enrichLog：把 lite 日志补成可展示项。没有标题也没有自定义名时给 `(session)` 兜底（否则崩溃/大上下文会话会在 /resume 里彻底消失）；sidechain 与团队会话则直接从列表过滤掉。'''),
    (5105, 'after', r'''enrichLogs：从 startIndex 起持续补全，直到凑够 count 条有效结果或扫完；返回的 nextIndex 让渐进加载能从断点继续，并打印过滤统计便于排查「会话不见了」。'''),
]
